import os

def quote(s):
    return s.replace('\\', '\\\\').replace('"', '\\"').replace('\n', ' ')

def make_item(id_, level, week, weekEnd, subject, domain, title, competency, skills, activities, isFrench=False):
    f_flag = ", isFrench = true" if isFrench else ""
    return f"""        AnnualLessonItem(
            id = "{id_}",
            level = {level}, week = {week}, weekEnd = {weekEnd},
            subject = "{quote(subject)}",
            domain = "{quote(domain)}",
            title = "{quote(title)}",
            competency = "{quote(competency)}",
            skills = "{quote(skills)}",
            activities = "{quote(activities)}"{f_flag}
        )"""

